const row = $('Ler coleta').first().json || {};
const P = JSON.parse(row.pacote_json || '{}');
const C = { dominio: P.dominio };
const ut = { temas: P.temas || [] };
const fontesIndisponiveis = (P.fontesIndisponiveis || []).slice();
// Google Trends
const trItems = $('Apify · resultado Trends').all().map((i) => i.json || {});
const media = (a) => a.length ? Math.round(a.reduce((s, v) => s + v, 0) / a.length) : null;
const trends = trItems.filter((t) => t.searchTerm || t.inputUrlOrTerm).map((t) => {
  const vals = (t.interestOverTime_timelineData || []).map((p) => Array.isArray(p.value) ? p.value[0] : p.value).filter((v) => typeof v === 'number');
  const sub = (t.interestBySubregion || []).find((x) => /goi/i.test(x.geoName || ''));
  return {
    termo: t.searchTerm || t.inputUrlOrTerm,
    interesse_medio_3m: media(vals), ultimas_4_semanas: media(vals.slice(-4)), primeiras_4_semanas: media(vals.slice(0, 4)),
    interesse_goias: sub ? (Array.isArray(sub.value) ? sub.value[0] : sub.value) : null,
    buscas_em_alta: (t.relatedQueries_rising || []).slice(0, 5).map((x) => x.query + (x.formattedValue ? ' (' + x.formattedValue + ')' : '')),
    buscas_relacionadas: (t.relatedQueries_top || []).slice(0, 5).map((x) => x.query)
  };
});
const trErr = row.trends_run ? trItems.find((t) => t.error) : null;
if (!row.trends_run) {}
else if (trErr) fontesIndisponiveis.push('Google Trends (Apify): ' + String(trErr.error.message || trErr.error).slice(0, 150));
else if (!trends.length) fontesIndisponiveis.push('Google Trends (Apify): sem resultado para os temas ' + JSON.stringify(ut.temas || []));

// AI Overviews
const aiItems = $('Apify · resultado AI Overviews').all().map((i) => i.json || {});
const aio = aiItems.filter((a) => a.query).map((a) => {
  const fontes = (a.sources || []).map((s) => s.url || '');
  return { consulta: a.query, tem_ai_overview: !!(a.text && String(a.text).trim()), resumo: String(a.text || '').slice(0, 700), dominio_citado: fontes.some((u) => u.indexOf(C.dominio) >= 0), fontes_citadas: fontes.slice(0, 8) };
});
const aiErr = row.aio_run ? aiItems.find((a) => a.error) : null;
if (row.aio_run && !aiErr && !aio.length) fontesIndisponiveis.push('AI Overviews (Apify): nenhum AI Overview retornado para os temas ' + JSON.stringify(ut.temas));
if (aiErr) fontesIndisponiveis.push('AI Overviews (Apify): ' + String(aiErr.error.message || aiErr.error).slice(0, 150));

const dataBR = P.dataBR;
const dossie = {
  cliente: { nome: P.nome, dominio: P.dominio, data_auditoria: dataBR, periodo_gsc: P.periodos },
  fontes_indisponiveis: fontesIndisponiveis,
  comparativo_com_auditoria_anterior: P.temAnterior ? P.comparativo : 'primeira auditoria deste cliente',
  auditoria_anterior: P.anterior,
  auditoria_tecnica: P.auditoria,
  search_console: P.gsc,
  position_tracking: { resumo: P.resumoPosicoes, palavras: P.palavras },
  backlinks: { resumo: P.backlinksInfo, dominios_de_referencia_mais_recentes: P.novosDominios },
  google_trends: { temas: ut.temas, resultados: trends },
  ai_overviews: aio,
  status_paginas_com_trafego: P.statusPaginas,
  alertas_automaticos: P.alertasAuto
};
const system = 'Você é o estrategista sênior de SEO e GEO da ATOM Digital, agência de Goiânia com 15 anos de SEO. Você escreve a auditoria de SEO que cada cliente recebe a cada 10 dias. Regras: use SOMENTE os números do dossiê; nunca invente dados, volumes ou causas; quando algo for hipótese, diga que é hipótese. Compare com a auditoria anterior sempre que houver. Se uma fonte estiver indisponível, diga isso em uma linha e siga com as demais. Escreva em português do Brasil, direto e concreto. Evite as expressões "no mundo atual", "cada vez mais", "é fundamental" e "vale ressaltar". Classifique alertas em 🔴 CRÍTICO, 🟠 ALTO e 🟡 MÉDIO.';
const prompt = 'Monte a auditoria de SEO de ' + P.nome + ' (' + P.dominio + ') de ' + dataBR + '. Responda em DUAS partes.\n\n' +
  'PARTE 1 — o relatório em HTML simples (somente h2, h3, p, ul, li, table, tr, th, td, strong; sem html, head, body, CSS ou markdown), nesta ordem: ' +
  '1) Resumo executivo: 3 a 5 pontos e uma nota geral de 0 a 10 com justificativa; ' +
  '2) Saúde técnica (Site Audit); ' +
  '3) Search Console: tráfego real, consultas e páginas que caíram ou subiram, oportunidades de CTR e de chegar à primeira página; ' +
  '4) Posições monitoradas; ' +
  '5) Backlinks e autoridade; ' +
  '6) Tendências de busca (Google Trends) e o que fazer com elas; ' +
  '7) AI Overviews e GEO: quais consultas têm AI Overview, se o site é citado e o que fazer para ser citado; ' +
  '8) Páginas com problema de status; ' +
  '9) Plano de ação dos próximos 10 dias em tabela (prioridade, ação, por quê, esforço baixo/médio/alto).\n\n' +
  'PARTE 2 — logo depois do HTML, os alertas em JSON puro entre as tags <alertas_json> e </alertas_json>: uma lista de objetos com nivel (CRITICO, ALTO ou MEDIO), area, titulo (até 80 caracteres, específico), evidencia (com o número do dossiê) e acao (concreta). Inclua os alertas automáticos que forem procedentes. Use CRITICO só para o que exige ação nesta rodada: queda forte de tráfego, página importante fora do ar ou erro técnico que bloqueia indexação.\n\n' +
  'DOSSIÊ (JSON):\n' + JSON.stringify(dossie).slice(0, 90000);

return [{ json: { filaId: row.id, nome: P.nome, dominio: P.dominio, inicioExecucao: P.inicioExecucao, dataBR: dataBR, periodos: P.periodos, campanha: P.campanha, metricas: P.metricas, comparativo: P.comparativo, temAnterior: P.temAnterior, alertasAuto: P.alertasAuto || [], fontesIndisponiveis: fontesIndisponiveis, system: system, prompt: prompt } }];

const D = $('Completar dossiê').first().json;
const j = $input.first().json || {};
let txt = '';
if (Array.isArray(j.content)) txt = j.content.map((c) => c.text || '').join('');
else txt = j.merged_response || j.text || j.output || '';
if (typeof txt !== 'string') txt = JSON.stringify(txt);
const iaErro = j.error ? String(j.error.message || j.error).slice(0, 200) : (!txt ? 'sem resposta da IA' : '');
const esc = (s) => String(s === null || s === undefined ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const semAcento = (s) => String(s || '').normalize('NFD').replace(/[̀-ͯ]/g, '');
const crase = String.fromCharCode(96);

let alertasIA = [];
const m = txt.match(/<alertas_json>([\s\S]*?)<\/alertas_json>/);
if (m) { try { alertasIA = JSON.parse(m[1].split(crase).join('').replace(/^\s*json/i, '').trim()); } catch (e) { alertasIA = []; } }
let analise = (m ? txt.slice(0, m.index) : txt).split(crase + crase + crase + 'html').join('').split(crase + crase + crase).join('').trim();
const h2 = analise.indexOf('<h2');
if (h2 > 0) analise = analise.slice(h2);
if (!analise) analise = '<p><strong>Análise da IA indisponível nesta rodada</strong> (' + esc(iaErro) + '). Os indicadores e alertas automáticos acima foram coletados normalmente.</p>';

let alertas = (Array.isArray(alertasIA) ? alertasIA : []).filter((a) => a && a.titulo);
if (!alertas.length) alertas = D.alertasAuto.slice();
alertas.forEach((a) => { a.nivel = semAcento(String(a.nivel || 'MEDIO')).toUpperCase(); if (['CRITICO', 'ALTO', 'MEDIO'].indexOf(a.nivel) < 0) a.nivel = 'MEDIO'; });
const ordem = { CRITICO: 0, ALTO: 1, MEDIO: 2 };
alertas.sort((a, b) => ordem[a.nivel] - ordem[b.nivel]);
const emoji = { CRITICO: '🔴', ALTO: '🟠', MEDIO: '🟡' };

const rotulos = [
  ['paginas_com_problemas_pct', 'Páginas com problemas (% das rastreadas)', -1], ['erros', 'Erros técnicos', -1], ['avisos', 'Avisos técnicos', -1],
  ['gsc_cliques', 'Cliques no Google (28 dias)', 1], ['gsc_impressoes', 'Impressões no Google (28 dias)', 1], ['gsc_posicao_media', 'Posição média (GSC)', -1],
  ['kw_top3', 'Palavras no top 3', 1], ['kw_top10', 'Palavras no top 10', 1], ['visibilidade', 'Visibilidade (Position Tracking)', 1],
  ['authority_score', 'Authority Score', 1], ['dominios_referencia', 'Domínios de referência', 1], ['backlinks', 'Backlinks', 1]
];
const fmtN = (v) => (v === null || v === undefined) ? '—' : Number(v).toLocaleString('pt-BR');
const linhas = rotulos.map((r) => {
  const c = D.comparativo[r[0]] || {};
  let delta = '—';
  if (c.variacao !== null && c.variacao !== undefined) {
    const v = c.variacao;
    const bom = v === 0 ? null : (v * r[2] > 0);
    delta = (v > 0 ? '+' : '') + Number(v).toLocaleString('pt-BR') + (bom === null ? '' : (bom ? ' ▲' : ' ▼'));
  }
  return '<tr><td>' + r[1] + '</td><td>' + fmtN(c.atual) + '</td><td>' + fmtN(c.auditoria_anterior) + '</td><td>' + delta + '</td></tr>';
}).join('');

const listaAlertas = alertas.length ? '<ul>' + alertas.map((a) => '<li>' + emoji[a.nivel] + ' <strong>' + esc(a.titulo) + '</strong>' + (a.area ? ' (' + esc(a.area) + ')' : '') + (a.evidencia ? ' — ' + esc(a.evidencia) : '') + (a.acao ? '<br>➡️ ' + esc(a.acao) : '') + '</li>').join('') + '</ul>' : '<p>Nenhum alerta nesta rodada.</p>';
const fontes = D.fontesIndisponiveis.length ? '<ul>' + D.fontesIndisponiveis.map((f) => '<li>' + esc(f) + '</li>').join('') + '</ul>' : '<p>Todas as fontes responderam nesta rodada.</p>';

const docHtml = '<html><head><meta charset="utf-8"></head><body>' +
  '<h1>Auditoria SEO — ' + esc(D.nome) + '</h1>' +
  '<p><strong>Site:</strong> ' + esc(D.dominio) + ' · <strong>Data:</strong> ' + esc(D.dataBR) + ' · <strong>Search Console:</strong> ' + D.periodos.atual[0] + ' a ' + D.periodos.atual[1] + ' vs. ' + D.periodos.anterior[0] + ' a ' + D.periodos.anterior[1] + ' · <strong>Posições:</strong> ' + esc(D.campanha) + ', últimos 10 dias</p>' +
  '<h2>Indicadores</h2><table border="1" cellpadding="6"><tr><th>Indicador</th><th>Agora</th><th>Auditoria anterior</th><th>Variação</th></tr>' + linhas + '</table>' +
  (D.temAnterior ? '' : '<p><em>Primeira auditoria deste cliente: as variações aparecem a partir da próxima rodada.</em></p>') +
  '<h2>Alertas</h2>' + listaAlertas +
  analise +
  '<h2>Fontes e limitações desta rodada</h2>' + fontes +
  '<p><em>Gerado automaticamente pelo n8n (ATOM · Auditoria SEO 10 dias) com dados de Semrush, Google Search Console, Google Trends e AI Overviews.</em></p>' +
  '</body></html>';

const b = 'atomauditoria' + Date.now();
const meta = { name: 'Auditoria SEO — ' + D.nome + ' — ' + D.dataBR, mimeType: 'application/vnd.google-apps.document', parents: ['1TIpJ8IRbTf0vp1MDo3RRlRumFuokxsYO'] };
const multipart = '--' + b + '\r\nContent-Type: application/json; charset=UTF-8\r\n\r\n' + JSON.stringify(meta) + '\r\n--' + b + '\r\nContent-Type: text/html; charset=UTF-8\r\n\r\n' + docHtml + '\r\n--' + b + '--';

return [{ json: { nome: D.nome, dominio: D.dominio, inicioExecucao: D.inicioExecucao, metricas: D.metricas, alertas: alertas, iaErro: iaErro, boundary: b, multipart: multipart } }];

// Só alertas 🔴 CRÍTICO viram card; no máximo 5 por cliente; não repete o mesmo alerta por 30 dias
const R = $('Preparar relatório').first().json;
const docJ = $('Criar Google Doc').first().json || {};
const doc = docJ.webViewLink || '';
const norm = (s) => String(s || '').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/[0-9]+/g, '#').replace(/[^a-z#]+/g, ' ').trim();
const existe = {};
$input.all().forEach((i) => { const r = i.json || {}; if (r.chave && r.criado_em && (Date.now() - Date.parse(r.criado_em)) < 30 * 864e5) existe[r.chave] = 1; });
const out = [];
(R.alertas || []).filter((a) => a.nivel === 'CRITICO').slice(0, 5).forEach((a) => {
  const chave = R.dominio + '|' + norm(a.area) + '|' + norm(a.titulo).slice(0, 80);
  if (existe[chave]) return;
  existe[chave] = 1;
  out.push({ json: {
    chave: chave, dominio: R.dominio, titulo: String(a.titulo).slice(0, 200),
    nome_card: '🔴 SEO · ' + R.nome + ' — ' + String(a.titulo).slice(0, 90),
    descricao: '**Cliente:** ' + R.nome + ' (' + R.dominio + ')\n**Área:** ' + (a.area || '-') + '\n\n**Evidência:** ' + (a.evidencia || '-') + '\n\n**O que fazer:** ' + (a.acao || '-') + (doc ? '\n\n📄 Auditoria completa: ' + doc : '') + '\n\n_Criado automaticamente pela auditoria de SEO de 10 dias._'
  } });
});
return out;
